Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PECH4.
Import PMS. Import PECH.
Local Ltac lia := PMK.alia.

Section Stage.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PECKS.klayout_S L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ptr ra : Z).
Variable payload : list byte.
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : PECH.n payload < 2 ^ 26.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 67584.
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Lemma stage4 :
  PMSP.syscat_spec RSEGS AD L HI -> PMSP.reset_spec RSEGS AD L HI ->
  forall (fx : FPState) R M model cr s s2 sm qc b K,
    PECH.H3 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R M model cr s s2 sm qc b -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        PECH.H4 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R1 M1 model1 cr s s2 sm qc b ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x34aa0 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x34a84 M model) K.
Proof.
